/* A case investigation: trainee observes; qualified staff service and start the rig. */
(() => {
  'use strict';
  const role = window.OchakovoShift.roles.engineering;
  Object.assign(role, {
    role:'Инженер по автоматизации',
    lead:'Бутылки проходят, а механизм ждёт. Разберись в причине вместе с инженером-наставником.',
    day:'Команда следит за повторными остановками и замечаниями операторов, проводит осмотры и обслуживание. Инженер сопоставляет движение механизмов и сигналы, обращается к документации, проверяет результат и передаёт оборудование в работу. Стажёр наблюдает и рассуждает рядом с наставником.',
    tools:'Схема линии, сигналы датчиков, история обслуживания, сообщения операторов и запись выполненных работ.',
    learned:'Сопоставил движение бутылок и сигналы, обосновал проверку гипотезы и оформил результат вместе с наставником.'
  });
  Object.assign(window.GameMissions.list.find(x=>x.id==='engineering'),{role:role.role,minutes:10});
  window.OchakovoShift.register('engineering', a => {
    const {button:b}=a;
    const steps=['Сообщение','Схема','Сигналы','Гипотезы','Работа','Проверка','Запись'];
    const titles=['Сначала — слова оператора','Где движение становится сигналом?','Бутылка и сообщение о ней','У каждой версии — своё основание','Что предложишь наставнику?','Работа выполнена. А результат?','Точная запись для следующей смены'];
    const lessons=['Уточни симптомы и передай инженеру факты.','Выбери точку, где сравнить движение и регистрацию.','Найди проходы, в которых бутылка есть, а сообщения о ней нет.','Сопоставь документацию, историю и текущее состояние.','Выбери следующий шаг и объясни, на что опираешься.','Сравни распознавание, передачу сигнала и работу механизма.','Зафиксируй, что обнаружено, выполнено и проверено.'];
    const signals=[1,0,1,1,0,1];
    const questions=[
      ['Что происходило перед остановкой?','Бутылки шли, но группа не выпускалась. Иногда следующая бутылка проходила, а счёт на панели не менялся.','Сравним физическое движение и регистрацию. Одна надпись на панели ещё не объясняет причину.'],
      ['Когда началось? Сбой повторялся?','После нескольких нормальных групп. Потом было ещё два таких ожидания. Запись последнего случая сохранил.','Повторяющийся сбой — повод искать закономерность. Запись поможет сравнить один и тот же момент.'],
      ['Менялись бутылки, подача, настройки?','Тот же учебный комплект. Скорость и настройки не менял. Бутылки подавались по одной.','Это точка сравнения. Слова оператора проверим по записи и истории обслуживания.'],
      ['В каком состоянии участок сейчас?','Остановил штатным способом и сообщил наставнику. Внутрь оборудования не заходил.','Одной остановки недостаточно для безопасного обслуживания — условия подготовит специалист.'],
      ['Есть повреждения или застрявшие бутылки?','Видимых повреждений не заметил. Перед остановкой бутылки у направляющих не застревали.','Полезное наблюдение, но отсутствие видимых повреждений ещё не объясняет пропуски счёта.']
    ];
    const reports=[['repeat','Ожидание группы повторялось после нормальной работы.'],['replace','Датчик S1 неисправен и требует замены на запасной.'],['mismatch','Бутылки проходили, а счёт увеличивался не каждый раз.'],['same','По словам оператора, комплект и настройки прежние.'],['stopped','Участок остановлен, запись события сохранена.']];
    const zones=[
      ['feed','Подача','Бутылки идут по одной','Подача влияет на распознавание. Но бутылки доходят до S1. Сравним, появляются ли сообщения о них в этой точке.'],
      ['sensor','Распознавание S1','Появляется сообщение о бутылке','Здесь движение впервые превращается в информацию. Мы выбрали место проверки, а не доказали поломку датчика.'],
      ['group','Группирование','Механизм ждёт шесть регистраций','Механизм может быть неисправен. Сначала выясним, выполнилось ли условие его работы: на панели пока четыре из шести.'],
      ['next','Передача дальше','Следующий участок готов','Занятость следующего участка могла бы задержать группу. Но здесь приём готов, а счёт ещё не набран.']
    ];
    const sources=[
      {id:'doc',name:'Описание и схема S1',kind:'Документация',title:'Что именно сообщает датчик',text:'S1 распознаёт непрозрачную учебную бутылку по отражённому свету. Его выход означает «бутылка распознана». Контроллер получает сообщение и ведёт счёт. Загрязнение оптического окна и изменение положения могут мешать распознаванию.',fact:'По описанию загрязнение окна может ослабить отражённый свет.'},
      {id:'history',name:'История обслуживания',kind:'Записи специалистов',title:'Что было до события',text:'При предыдущем осмотре распознавание было устойчивым. Положение и настройки зафиксированы. Позже использовался тот же учебный комплект. Записей об изменении настроек нет. Отсутствие записи не доказывает отсутствие любых изменений.',fact:'При предыдущем осмотре распознавание было устойчивым; изменений настроек не зарегистрировано.'},
      {id:'inspect',name:'Осмотр зоны S1',kind:'Заключение специалиста',title:'Что обнаружено сейчас',text:'Осмотр выполнен квалифицированным специалистом после подготовки безопасных условий. На наружном оптическом окне виден матовый след. Крепление проверено, положение соответствует исходной отметке. Видимых повреждений корпуса нет.',fact:'На оптическом окне есть след; крепление и положение проверены.'},
      {id:'flow',name:'Движение и подача',kind:'Покадровые данные',title:'Проходят ли бутылки отдельно',text:'Бутылки проходят S1 по одной, с видимыми промежутками. Путь одинаковый; остановок перед датчиком и заметного изменения скорости нет. Версия о бутылках, идущих вплотную, этой записью не поддерживается.',fact:'Бутылки идут отдельно; подача без видимых нарушений.'},
      {id:'wire',name:'Сигналы и изменения',kind:'Диагностическая запись',title:'Доходит ли сообщение',text:'Вход контроллера повторяет выход S1 во всех шести проходах. Доступная диагностика питания — без отклонений. Зарегистрированных изменений параметров в период события нет. Полную исправность электроники эти сведения не доказывают.',fact:'Выход S1 и вход контроллера совпадают; питание без зарегистрированных отклонений.'},
      {id:'gate',name:'Узел группирования',kind:'Состояние механизма',title:'Почему механизм ждёт',text:'Состояние — «Ожидание счёта». Команда выпуска группы не выдавалась: зарегистрированы четыре бутылки из шести. Следующий участок готов. Реальное движение механизма проверят после обслуживания.',fact:'Команда выпуска не выдавалась: условие счёта не выполнено.'},
      {id:'parts',name:'Каталог запасных частей',kind:'Справочник',title:'Что можно заменить',text:'Для стенда предусмотрен совместимый запасной датчик. Каталог помогает подобрать замену, когда её необходимость установлена. Наличие запасной детали ничего не говорит о причине сбоя.',fact:''}
    ];
    const hypotheses=[
      {id:'spacing',title:'Бутылки идут вплотную',source:'flow',reply:'Между бутылками видны промежутки, а пропуск возникает при бутылке в зоне. В этой записи версия не подтверждается.'},
      {id:'position',title:'Датчик сместился',source:'inspect',reply:'Специалист проверил крепление и исходную отметку — изменений не нашёл. Оснований для этой версии стало меньше.'},
      {id:'dirt',title:'Свету мешает налёт на окне',source:'inspect',reply:'Есть след на окне, а описание S1 объясняет его влияние. Это ведущая гипотеза; её ещё нужно проверить результатом обслуживания.'},
      {id:'transfer',title:'Теряется передача сигнала',source:'wire',reply:'Вход контроллера повторяет выход S1. Пропуски уже возникают при распознавании, до передачи.'},
      {id:'electronics',title:'Неисправна электроника S1',source:'wire',reply:'Пока исключить нельзя. Но видимый след даёт конкретное условие для проверки. Если сбой сохранится, специалист продолжит диагностику.'}
    ];
    const evidence=[['wire','Выход S1 совпадает со входом контроллера'],['inspect','На оптическом окне обнаружен матовый след'],['history','Раньше распознавание было устойчивым'],['doc','Загрязнение окна может мешать отражённому свету']];
    const actions=[
      ['settings','Изменить настройку распознавания','Настройка иногда нужна при других объектах или условиях. Здесь комплект прежний, а на окне есть след. Изменение параметров может скрыть проблему и усложнить сравнение.'],
      ['clean','Обслужить наружное оптическое окно','Есть наблюдение и понятная связь с работой датчика. Проверим эту гипотезу, затем сравним результат в прежних условиях.'],
      ['replace','Заменить S1 на запасной датчик','Внутренняя неисправность остаётся версией. Сначала проверим конкретное внешнее условие. Если сбой сохранится, специалист продолжит диагностику.'],
      ['drive','Проверить привод группирователя','Движение проверим при испытании. В исходной записи команды выпуска не было — счёт не набран. Сейчас ожидание механизма объясняется этим.']
    ];
    const fields=[
      {name:'Что заметили',options:['Шесть бутылок прошли S1, зарегистрированы четыре; механизм ожидал группу.','Шесть бутылок зарегистрированы, выпущены четыре; механизм задерживал группу.'],correct:0,reply:'Регистрация и выпуск — разные события. В исходной записи счёт был четыре при шести бутылках.'},
      {name:'Что установили',options:['После восстановления передачи сигнала пропуски исчезли; распознавание S1 совпало.','После обслуживания окна пропуски S1 не повторились; передача сигнала совпала.'],correct:1,reply:'Передачу не восстанавливали: вход и выход совпадали до работы. Обслужили оптическое окно.'},
      {name:'Что выполнено',options:['Специалист восстановил положение датчика; окно и настройки не менялись.','Специалист обслужил оптическое окно; положение и настройки не менялись.'],correct:1,reply:'Положение проверили и не меняли. Специалист обслужил наружное оптическое окно.'},
      {name:'Как проверили',options:['Два прохода по шесть: сигналы совпали, группы выпущены; в промежутке событий нет.','Один проход из шести: сигналы совпали, группа выпущена; второй проход не проверяли.'],correct:0,reply:'Проверены оба прохода — A и B — и пустой промежуток между ними.'},
      {name:'Текущий статус',options:['Проверка завершена; передать результат оператору и ответственному за возобновление.','Проверка не завершена; передать оператору запрос на повтор всей диагностики.'],correct:0,reply:'Все критерии испытания проверены. Теперь нужна передача результата и согласование возобновления.'}
    ];
    const checks=['Все бутылки распознаны','Выход и вход совпали','В промежутке нет ложных событий','Обе группы выпущены'];
    const st={phase:0,unlocked:0,question:-1,asked:new Set(),report:new Set(),zone:'',frame:0,marked:new Set(),conclusion:'',signalReady:false,source:'doc',read:new Set(),hypothesis:'',linkSource:'',leading:'',links:{},nextAction:'',evidence:new Set(),work:0,test:0,criteria:new Set(),testConclusion:'',record:Array(5).fill(-1),invalid:[],handed:false,accepted:false,notebook:false,note:'',good:false};
    let alive=true;
    const tally=i=>signals.slice(0,i+1).reduce((n,v)=>n+v,0);
    const toggle=(set,v)=>set.has(v)?set.delete(v):set.add(v);
    const btn=(type,text,value='',cls='eng-button',attrs='')=>b(type,text,value,cls,attrs);
    const choice=(type,value,text,selected,multi=false)=>btn(type,`<span class="eng-choice-mark" aria-hidden="true">${selected?a.check:''}</span><span>${text}</span>`,value,`eng-choice ${selected?'is-selected':''} ${multi?'is-multiple':''}`,`aria-pressed="${selected}"`);
    function icon(name){const paths={book:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4Zm10 3a3 3 0 0 1 3-3h3v14h-2a4 4 0 0 0-4 3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.eye}"/></svg>`;}
    function bottles(index=-1){return Array.from({length:6},(_,i)=>{const x=index<0?107+i*69:320+(index-i)*55,active=i===index;return `<g class="eng-bottle ${active?'is-active':''}" transform="translate(${x} 108)"><path d="M-8 0h16v18l10 14v59a7 7 0 0 1-7 7h-22a7 7 0 0 1-7-7V32l10-14Z" fill="${active?'#fffdf8':'#e1ded6'}" stroke="${active?'#d50032':'#9f9c92'}" stroke-width="1.8"/><rect x="-9" y="-4" width="18" height="9" rx="2" fill="${active?'#d50032':'#867f72'}"/><rect x="-17" y="48" width="34" height="32" rx="2" fill="${active?'#d50032':'#bcb5a7'}"/><text y="70" text-anchor="middle" fill="${active?'white':'#373a34'}" font-size="17" font-weight="700">${i+1}</text></g>`;}).join('');}
    function scene(mode='stopped'){
      const replay=mode==='replay',testing=mode==='testing',running=mode==='running',cleaned=st.work>=3;
      const count=replay?tally(st.frame):testing?st.test===1?3:st.test===3?0:6:running?6:4;
      const lit=replay?!!signals[st.frame]:testing?st.test!==3:running;
      const release=running||(testing&&(st.test===2||st.test===4));
      const label=replay?'Запись до остановки':testing?'Испытание сотрудниками':running?'Участок возвращён в работу':st.work>0&&st.work<3?'Работает специалист':cleaned?'Ожидает испытания':'Остановлен оператором';
      return `<section class="eng-scene ${release?'is-running':''}" aria-label="Схема учебного участка"><div class="eng-scene-top"><span><i class="eng-status-dot ${release?'is-green':''}"></i>${label}</span><span>Учебная линия</span></div><svg viewBox="0 0 800 274" role="img" aria-label="Конвейер, датчик S1, контроллер: ${count} из 6. Механизм: ${release?'выпуск группы':'ожидание'}"><defs><marker id="eng-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="#89958b"/></marker></defs><path d="M52 214h600" stroke="#8b9187" stroke-width="3"/><rect x="44" y="216" width="625" height="24" rx="12" fill="#d6d6cb" stroke="#acafa3"/>${Array.from({length:17},(_,i)=>`<circle class="eng-roller" cx="${61+i*35}" cy="228" r="7" fill="#f3f2eb" stroke="#9a9e92"/>`).join('')}<path d="M90 240v22m500-22v22" stroke="#9a9e92" stroke-width="7"/>${testing&&st.test===3?'':bottles(replay?st.frame:testing?(st.test===1?2:5):-1)}<path d="M79 254h94m17 0h30" stroke="#89958b" stroke-width="1.5" marker-end="url(#eng-arrow)"/><g class="eng-sensor"><path d="M291 62v29m0-29h58" fill="none" stroke="#a1a89d" stroke-width="4"/><rect x="299" y="49" width="42" height="37" rx="5" fill="#39483e"/><circle cx="320" cy="70" r="8" fill="${cleaned?'#eaf1e8':'#a9b4a6'}"/>${!cleaned&&st.phase>=3&&st.read.has('inspect')?'<path d="m314 66 10 8m-11-4 9-6" stroke="#7d7764" stroke-width="3"/>':''}<circle cx="332" cy="55" r="3" fill="${lit?'#9ecba5':'#69786c'}"/><path d="M320 87v47" stroke="${lit?'#26704d':'#a4afa0'}" stroke-width="2" stroke-dasharray="4 4"/><text x="320" y="36" text-anchor="middle" fill="#39483e" font-size="15" font-weight="700">S1</text></g><path d="M343 65h207v38h145" fill="none" stroke="#a4afa0" stroke-width="1.5"/><g class="eng-panel"><rect x="692" y="61" width="87" height="136" rx="7" fill="#39483e"/><rect x="702" y="76" width="67" height="75" rx="3" fill="#f4f5eb"/><text x="735" y="96" text-anchor="middle" fill="#596552" font-size="11">СЧЁТ</text><text x="735" y="130" text-anchor="middle" fill="${release?'#26704d':'#39483e'}" font-size="29" font-weight="600">${count}<tspan font-size="15"> / 6</tspan></text><circle cx="716" cy="171" r="5" fill="${release?'#9ecba5':'#bcb9a1'}"/><text x="724" y="175" fill="#f0f2e9" font-size="11">${release?'ВЫПУСК':'ЖДЁТ'}</text></g><g class="eng-gate ${release?'is-open':''}"><path d="M647 126v85" stroke="#868b7f" stroke-width="7"/><rect x="621" y="149" width="53" height="10" rx="3" fill="#d50032"/></g><text x="94" y="88" fill="#6b7265" font-size="13">Подача</text><text x="593" y="108" text-anchor="middle" fill="#6b7265" font-size="13">Группирование</text></svg><div class="eng-scene-foot"><span>${replay?`Проход ${st.frame+1} из 6 · бутылка в зоне S1`:'Бутылка → датчик → контроллер → механизм'}</span><span>${release?'Группа выпущена':`${count} из 6 зарегистрировано`}</span></div></section>`;
    }
    function next(type,label,hint=''){return `<div class="eng-actions">${hint?`<p>${hint}</p>`:'<span></span>'}${btn(type,`${label} ${a.arrow}`,'','primary')}</div>`;}
    function notebook(){const facts=[];if(st.asked.has(0))facts.push('Оператор: бутылки проходят, счёт меняется не всегда.');if(st.asked.has(1))facts.push('Сбой повторялся, запись сохранена.');if(st.asked.has(3))facts.push('Участок остановлен оператором.');if(st.signalReady)facts.push('Проходы 2 и 5: бутылка есть, выхода S1 нет; вход повторяет S1.');sources.filter(s=>st.read.has(s.id)&&s.fact).forEach(s=>facts.push(s.fact));return `<details class="eng-notebook" ${st.notebook?'open':''}><summary>${icon('book')} Блокнот диагностики <span>Наблюдений: ${facts.length}</span></summary><div class="eng-notebook-body"><h4>Наблюдения</h4>${facts.length?`<ul>${facts.map(x=>`<li>${x}</li>`).join('')}</ul>`:'<p>Здесь появятся ответы оператора и сведения проверки.</p>'}<h4>Предположения</h4><p>${(st.leading||st.hypothesis)?hypotheses.find(h=>h.id===(st.leading||st.hypothesis)).title+' — '+(st.test>=4&&(st.leading||st.hypothesis)==='dirt'?'подтверждено результатом в учебных условиях.':'требует проверки.'):'Причина пока не установлена.'}</p><h4>Проверено</h4><p>${st.test>=4?'Два прохода по шесть, промежуток без ложных событий, обе группы выпущены.':st.work>=3?'Окно обслужено специалистом. Результат ещё проверяем.':'Работы и результаты появятся после испытания.'}</p></div></details>`;}
    function operatorStage(){const q=questions[st.question];return `${scene()}<div class="eng-task-grid"><section class="eng-conversation"><div class="eng-person"><span class="eng-avatar">О</span><div><h3>Оператор линии</h3><span>Сообщение с участка</span></div></div><blockquote>«Бутылки уже у группирователя, а он всё ждёт. Участок остановлен. Нужна помощь».</blockquote><div class="eng-question-list">${questions.map((q,i)=>btn('ask',`<span>${q[0]}</span><span aria-hidden="true">${st.asked.has(i)?'✓':'+'}</span>`,i,`eng-question ${st.question===i?'is-active':''}`)).join('')}</div>${q?`<div class="eng-answer"><span>Оператор отвечает</span><p>${q[1]}</p><p class="eng-mentor-small"><strong>Наставник.</strong> ${q[2]}</p></div>`:'<p class="eng-help">Узнай, что происходило, повторялся ли сбой, что менялось и каков статус участка.</p>'}</section><section class="eng-report"><h3>Передай инженеру факты</h3><p class="eng-help">Отметь сведения для сообщения. Причину пока не называем.</p>${reports.map(([id,text])=>choice('report',id,text,st.report.has(id),true)).join('')}<details class="eng-inline-detail"><summary>Как команда следит за надёжностью</summary><p>Инженеры просматривают замечания операторов, историю коротких остановок и результаты осмотров. Плановые проверки помогают заметить повторяющийся сбой до серьёзной остановки. Оператор дополняет сигналы наблюдениями с места.</p></details></section></div>${next('check-report','Передать сообщение')}`;}
    function mapStage(){const z=zones.find(z=>z[0]===st.zone);return `${scene()}<div class="eng-line-map" aria-label="Зоны линии">${zones.map(([id,title,sub],i)=>btn('zone',`<span class="eng-zone-index">${i+1}</span><strong>${title}</strong><span>${sub}</span>`,id,`eng-zone ${st.zone===id?'is-selected':''}`,`aria-pressed="${st.zone===id}"`)).join('')}</div>${z?`<div class="eng-zone-note"><strong>${z[1]}</strong><p>${z[2]}. ${z[0]==='sensor'?'Здесь появляется информация для счёта. Сопоставим её с реальной бутылкой.':z[3]}</p></div>`:'<p class="eng-help">Исследуй зоны. Выбери, где начать сравнение движения и регистрации.</p>'}<details class="eng-inline-detail"><summary>Датчик, контроллер, механизм — простыми словами</summary><p>Датчик замечает объект. Контроллер выполняет программу: получает сообщения и ведёт счёт. Исполнительный механизм делает физическое действие по команде. Панель показывает данные контроллера; сама она не считает бутылки взглядом.</p></details>${next('check-zone','Проверить выбранную зону')}`;}
    function signalStage(){const n=signals[st.frame];return `${scene('replay')}<div class="eng-playback"><div class="eng-playback-title"><strong>Событие до остановки</strong><span>Оборудование сейчас остановлено</span></div><div class="eng-frames" aria-label="Покадровая запись">${signals.map((_,i)=>btn('frame',`<span>Бутылка</span><strong>${i+1}</strong><small>${st.marked.has(i)?'Отмечено':'Смотреть'}</small>`,i,`eng-frame ${st.frame===i?'is-active':''} ${st.marked.has(i)?'is-marked':''}`,`aria-pressed="${st.frame===i}"`)).join('')}</div><div class="eng-readings"><div><span>В зоне S1</span><strong>Бутылка есть</strong></div><div><span>Выход S1</span><strong>${n?'Распознана':'Не распознана'}</strong></div><div><span>Вход контроллера</span><strong>${n?'Распознана':'Не распознана'}</strong></div></div>${btn('mark',`${icon('eye')}${st.marked.has(st.frame)?'Убрать отметку расхождения':'Отметить расхождение в этом проходе'}`,'','eng-mark',`aria-pressed="${st.marked.has(st.frame)}"`)}<details class="eng-inline-detail"><summary>Все шесть проходов таблицей</summary><table class="eng-table"><thead><tr><th>Проход</th><th>Бутылка</th><th>S1</th><th>Вход</th><th>Счёт</th></tr></thead><tbody>${signals.map((v,i)=>`<tr><th>${i+1}</th><td>Есть</td><td>${v?'Да':'Нет'}</td><td>${v?'Да':'Нет'}</td><td>${tally(i)}</td></tr>`).join('')}</tbody></table></details></div><section class="eng-decision"><h3>Какой вывод подтверждает запись?</h3><div class="eng-choices">${[['wire','Часть сигналов теряется на пути к контроллеру'],['detect','Часть бутылок не распознаётся в зоне S1'],['gate','Группирователь не выполняет полученную команду'],['feed','Бутылки не доходят до зоны распознавания']].map(([id,text])=>choice('signal-conclusion',id,text,st.conclusion===id)).join('')}</div></section>${next('check-signals','Сопоставить наблюдения',`Отмечено проходов: ${st.marked.size}`)}`;}
    function hypothesisStage(){const source=sources.find(s=>s.id===st.source);return `<div class="eng-evidence-work"><section class="eng-source-list"><h3>Диагностическое досье</h3>${sources.map(s=>btn('source',`<span>${s.name}</span><small>${st.read.has(s.id)?'Прочитано':s.kind}</small>`,s.id,`eng-source ${st.source===s.id?'is-active':''}`,`aria-pressed="${st.source===s.id}"`)).join('')}</section><article class="eng-document"><div class="eng-document-title">${icon('book')}<span>${source.kind}</span></div><h3>${source.title}</h3>${source.id==='inspect'?'<div class="eng-optic" role="img" aria-label="Осмотр: матовый след на окне, положение крепления не изменено"><div class="eng-optic-face"><i></i></div><div><strong>Окно S1</strong><span>Матовый след на поверхности</span><span>Положение — по исходной отметке</span></div></div>':''}<p>${source.text}</p>${btn('read-source',st.read.has(source.id)?'Сведения в блокноте':'Добавить наблюдение в блокнот',source.id,'eng-document-save',st.read.has(source.id)?'disabled':'')}<p class="eng-document-caption">Учебные сведения о стенде · ${source.name}</p></article></div><section class="eng-hypothesis"><h3>Свяжи версию с наблюдением</h3><p class="eng-help">Выбери версию, затем источник, который позволяет её проверить.</p><div class="eng-hypothesis-buttons">${hypotheses.map(h=>choice('hypothesis',h.id,`${h.title}${st.links[h.id]?'<small>Сопоставлено</small>':''}`,st.hypothesis===h.id)).join('')}</div>${st.hypothesis?`<fieldset class="eng-source-picker"><legend>На какие сведения опираешься?</legend>${sources.filter(s=>st.read.has(s.id)).map(s=>choice('link-source',s.id,s.name,st.linkSource===s.id)).join('')}${!st.read.size?'<p>Добавь наблюдения из досье.</p>':''}</fieldset>${btn('link-hypothesis','Сопоставить версию с данными','','secondary')}`:''}</section>${next('check-hypotheses','Выбрать ведущую гипотезу','Изучи описание S1, историю и осмотр. Сопоставь минимум две версии.')}`;}
    function workStage(){
      if(st.work>0){const scenes=[null,['Безопасные условия готовит специалист','Наставник согласует работу с оператором, предотвращает неожиданный пуск и учитывает источники энергии по применимой инструкции. Стажёр остаётся вне зоны обслуживания. Одной остановки на панели недостаточно.','Наблюдать подготовку условий'],['Наставник выполняет обслуживание','Специалист подтвердил безопасные условия и обслуживает наружное оптическое окно по документации. Способ и средства выбираются для оборудования. Стажёр не открывает ограждения и не вмешивается в оборудование.','Посмотреть результат работы'],['Окно обслужено. Проверка ещё впереди','След удалён. Положение и настройки не менялись: изменили одно условие, чтобы сравнение было понятным. Специалист проверяет восстановление защит и отсутствие людей в опасной зоне. С оператором согласуется испытание.','Перейти к испытанию']],w=scenes[st.work];return `${scene()}<section class="eng-work-story"><span class="eng-avatar eng-avatar-mentor">И</span><div><h3>${w[0]}</h3><p>${w[1]}</p><div class="eng-work-progress">${['Безопасность','Обслуживание','Подготовка испытания'].map((x,i)=>`<span class="${i<st.work?'is-done':''}">${i+1}. ${x}</span>`).join('')}</div><details class="eng-inline-detail"><summary>Почему способ работы берут из документации?</summary><p>У разных узлов различаются конструкция, материалы и ограничения. Документация помогает выбрать допустимый способ обслуживания. В игре нет универсального рецепта ремонта.</p></details></div></section>${next('work-next',w[2])}`;}
      return `${scene()}<div class="eng-action-brief"><strong>Ведущая гипотеза</strong><p>Загрязнение оптического окна мешает распознаванию. Это ещё предстоит подтвердить.</p></div><section class="eng-decision"><h3>Какую работу предложишь специалисту?</h3><div class="eng-choices">${actions.map(([id,text])=>choice('next-action',id,text,st.nextAction===id)).join('')}</div></section><fieldset class="eng-evidence-pick"><legend>Выбери основания для предложения</legend>${evidence.map(([id,text])=>choice('evidence',id,text,st.evidence.has(id),true)).join('')}</fieldset>${next('propose','Обсудить с наставником')}`;
    }
    function testStage(){
      if(st.test===0)return `${scene()}<section class="eng-test-plan"><h3>Сравнение в прежних условиях</h3><p>Тот же комплект, прежние положение и настройки, обычный темп стенда. Пуском управляют сотрудники.</p><ol><li>Полный проход шести бутылок.</li><li>Пустой промежуток — без ложных сообщений.</li><li>Повторный проход и выпуск второй группы.</li></ol><p class="eng-help">Это объём учебного испытания, а не норматив приёмки оборудования компании.</p></section>${next('test-start','Наблюдать проверку')}`;
      if(st.test===1)return `${scene('testing')}<section class="eng-test-plan"><h3>Три бутылки — три распознавания</h3><p>Начало первого прохода: выход S1 и вход совпадают. Счёт — 3 из 6. Механизм ждёт полной группы.</p><h3>Достаточно ли этого?</h3><div class="eng-choices">${[['resume','Предложить возврат участка к работе'],['continue','Предложить завершить намеченную проверку'],['replace','Предложить дополнительную замену датчика']].map(([id,text])=>btn('early-test',text,id,'eng-choice eng-plain-choice')).join('')}</div></section>`;
      const rows=[['Проход A','6 из 6','Выход S1 совпал со входом. Группа выпущена.',st.test>=2],['Пустой промежуток','0 событий','Бутылок нет, ложных регистраций нет.',st.test>=3],['Проход B','6 из 6','Новый цикл: счёт от 0 до 6. Вторая группа выпущена.',st.test>=4]];
      return `${scene('testing')}<div class="eng-test-results">${rows.map(([name,result,body,show])=>`<div class="eng-test-result ${show?'is-done':''}"><span>${name}</span><strong>${show?result:'Не проверено'}</strong><p>${show?body:'Наблюдение впереди'}</p></div>`).join('')}</div>${st.test<4?next('test-next',st.test===2?'Наблюдать пустой промежуток':'Наблюдать второй проход'):`<fieldset class="eng-evidence-pick"><legend>Что подтверждает результат?</legend>${checks.map((text,i)=>choice('criterion',i,text,st.criteria.has(i),true)).join('')}</fieldset><section class="eng-decision"><h3>Твоё заключение</h3><div class="eng-choices">${[['mechanism','Распознавание восстановлено, механизму нужна наладка'],['success','Распознавание восстановлено, работа узла проверена'],['transfer','Распознавание нестабильно, нужна проверка передачи']].map(([id,text])=>choice('test-conclusion',id,text,st.testConclusion===id)).join('')}</div></section>${next('accept-test','Сверить результат с наставником')}`}`;
    }
    function recordStage(){
      if(st.accepted)return `${scene('running')}<section class="eng-closed"><h3>Участок снова в работе</h3><p>Оператор возобновил работу после согласования. Следующая группа проходит устойчиво.</p><div class="eng-handoff-lines"><p><strong>Наставник</strong> подтвердил выполненную работу, безопасную готовность и результат проверки.</p><p><strong>Оператор</strong> принял участок и наблюдает дальнейшую работу.</p></div><p>Ты проследил путь от сообщения оператора до подтверждённого результата. Надёжность оборудования — совместная работа команды.</p></section>${next('finish','Записать открытие')}`;
      if(st.handed)return `${scene()}<section class="eng-handoff"><h3>Запись передана. Согласуем возвращение</h3><div class="eng-record-paper"><h4>Учебный узел группирования · S1</h4>${fields.map((f,i)=>`<p><strong>${f.name}.</strong> ${f.options[st.record[i]]}</p>`).join('')}<p><strong>При повторении:</strong> сообщить о новом событии, сохранить наблюдения, обратиться к наставнику.</p></div><div class="eng-handoff-lines"><p><strong>Инженер-наставник:</strong> «Работа и проверка завершены. Подтверждаю результат и согласую возобновление как ответственный в учебной модели».</p><p><strong>Оператор:</strong> «Счёт совпал с бутылками, обе группы выпущены. Результат получил, готов наблюдать работу».</p></div><p class="eng-help">Роли заданы для сюжета. Внутренний порядок согласования «Очаково» не предполагается.</p></section>${next('handoff','Наблюдать возвращение к работе')}`;
      return `<div class="eng-record-intro">${icon('book')}<p>Следующая смена должна понять, что произошло и что уже проверено. Выбери точные строки записи.</p></div><div class="eng-record-fields">${fields.map((f,i)=>`<fieldset class="${st.invalid.includes(i)?'has-error':''}"><legend>${i+1}. ${f.name}</legend>${f.options.map((text,j)=>choice('record',`${i}:${j}`,text,st.record[i]===j)).join('')}${st.invalid.includes(i)?`<p class="eng-field-error">${st.record[i]<0?'Выбери формулировку.':f.reply}</p>`:''}</fieldset>`).join('')}</div><div class="eng-action-brief"><strong>Если сбой повторится</strong><p>Сообщить о новом событии, сохранить наблюдения и обратиться к наставнику. Проверка подтверждает результат в проверенных условиях; наблюдение продолжается.</p></div>${next('save-record','Передать запись наставнику')}`;
    }
    const renderers=[operatorStage,mapStage,signalStage,hypothesisStage,workStage,testStage,recordStage];
    function render(){if(!alive)return;const opened=a.root.querySelector('.eng-notebook');if(opened)st.notebook=opened.open;
      a.draw(`<div class="eng-workshop" data-engineering-phase="${st.phase+1}"><nav class="eng-progress" aria-label="Этапы инженерного расследования">${steps.map((name,i)=>btn('step',`<span>${i<st.unlocked?a.check:i+1}</span><small>${name}</small>`,i,`eng-step ${i===st.phase?'is-current':''} ${i<st.unlocked?'is-done':''}`,`aria-label="${i+1}. ${name}" ${i>st.unlocked?'disabled':''} ${i===st.phase?'aria-current="step"':''}`)).join('')}</nav><header class="eng-phase-title"><div><h3 tabindex="-1" id="eng-stage-title">${titles[st.phase]}</h3><p>${lessons[st.phase]}</p></div><span>${st.phase+1} / 7</span></header>${renderers[st.phase]()}${st.note?`<div class="eng-response ${st.good?'is-success':''}" role="status" tabindex="-1"><span class="eng-avatar eng-avatar-mentor">И</span><div><strong>Инженер-наставник</strong><p>${st.note}</p></div></div>`:''}${notebook()}<p class="eng-model-note">Учебный стенд: ситуация, обозначения и параметры условные. Стажёр наблюдает и предлагает решения; обслуживание и пуск выполняют сотрудники.</p></div>`,[],0,'');
    }
    function focusAfterDraw(selector,scroll=false){Promise.resolve().then(()=>{if(!alive)return;const target=a.root.querySelector(selector);target?.focus({preventScroll:true});if(scroll)target?.scrollIntoView({block:'nearest',behavior:'instant'});});}
    function talk(text,ok=false){st.note=text;st.good=ok;render();a.say(text,ok?'success':'think');focusAfterDraw('.eng-response',true);}
    function move(n){st.phase=n;st.unlocked=Math.max(st.unlocked,n);st.note='';render();a.say(lessons[n]);focusAfterDraw('#eng-stage-title');a.root.querySelector('.eng-progress')?.scrollIntoView({block:'start',behavior:'instant'});}
    function act(type,value){
      if(type==='step'){const n=Number(value);if(Number.isInteger(n)&&n>=0&&n<=st.unlocked)move(n);return;}
      if(st.handed&&type!=='handoff')return;
      st.note='';
      if(st.phase===0){
        if(type==='ask'){const n=Number(value);if(questions[n]){st.question=n;st.asked.add(n);render();a.say(questions[n][2]);}}
        if(type==='report'){toggle(st.report,value);render();}
        if(type==='check-report'){const missing=[0,1,2,3].find(n=>!st.asked.has(n));if(missing!==undefined)return talk('Уточни у оператора: '+questions[missing][0].toLowerCase());if(st.report.has('replace'))return talk('Замена S1 — пока предположение. Передай наблюдения, а необходимость замены проверим.');if(!['repeat','mismatch','same','stopped'].every(id=>st.report.has(id)))return talk('Добавь наблюдаемое расхождение, повторяемость, условия и статус участка. Сообщение должно помочь начать проверку.');move(1);}
      }else if(st.phase===1){
        if(type==='zone'){st.zone=value;render();}
        if(type==='check-zone'){const z=zones.find(z=>z[0]===st.zone);if(!z)return talk('Выбери зону, где можно сравнить бутылку с сообщением о ней.');if(st.zone!=='sensor')return talk(z[3]);move(2);talk(z[3],true);}
      }else if(st.phase===2){
        if(type==='frame'){const n=Number(value);if(n>=0&&n<6){st.frame=n;render();}}
        if(type==='mark'){toggle(st.marked,st.frame);render();}
        if(type==='signal-conclusion'){st.conclusion=value;render();}
        if(type==='check-signals'){
          if(st.marked.size!==2||!st.marked.has(1)||!st.marked.has(4))return talk('В отмеченном проходе сравни наличие бутылки и выход S1. Нужны все проходы, где бутылка есть, но сообщения о ней нет. Таблица позволяет проверить себя.');
          if(st.conclusion==='wire')return talk('Выход S1 и вход совпадают в каждый момент. При потере передачи мы ожидали бы сигнал на выходе, которого нет на входе.');
          if(st.conclusion==='gate')return talk('Зарегистрированы четыре из шести. Команда выпуска не выдавалась. По ожиданию нельзя заключить, что механизм не исполнил команду.');
          if(st.conclusion==='feed')return talk('Во втором и пятом проходах бутылка находится в зоне S1. Пропадает сообщение о ней, а не сама бутылка.');
          if(st.conclusion!=='detect')return talk('Выбери вывод и опирайся на отмеченные проходы.');
          st.signalReady=true;move(3);talk('Расхождение возникает при распознавании. Это признак, а причина пока не установлена. Открой описание, историю и осмотр.',true);
        }
      }else if(st.phase===3){
        if(type==='source'){if(sources.some(s=>s.id===value)){st.source=value;render();}}
        if(type==='read-source'){if(sources.some(s=>s.id===value)){st.read.add(value);render();if(value==='parts')a.say('Каталог поможет подобрать замену, когда её необходимость установлена. Сейчас он не объясняет причину.');}}
        if(type==='hypothesis'){if(hypotheses.some(h=>h.id===value)){st.hypothesis=value;st.linkSource='';render();}}
        if(type==='link-source'){st.linkSource=value;render();}
        if(type==='link-hypothesis'){const h=hypotheses.find(h=>h.id===st.hypothesis);if(!h||!st.linkSource)return talk('Выбери версию и источник из добавленных наблюдений.');if(st.linkSource!==h.source&&!(h.id==='dirt'&&st.linkSource==='doc'))return talk('Этот источник не проверяет версию напрямую. Найди сведения о '+(h.id==='spacing'?'движении бутылок.':h.id==='position'?'креплении и положении.':h.id==='transfer'?'выходе и входе сигнала.':h.id==='electronics'?'сигнале и питании.':'поверхности окна или принципе распознавания.'));st.links[h.id]=st.linkSource;talk(h.reply,true);}
        if(type==='check-hypotheses'){const missing=['doc','history','inspect'].find(id=>!st.read.has(id));if(missing)return talk('Добавь сведения из источника «'+sources.find(s=>s.id===missing).name+'»: нужны принцип работы, история и текущее состояние.');if(Object.keys(st.links).length<2)return talk('Сопоставь хотя бы две версии с наблюдениями. Пойми, почему одна ведущая, а другая ослабла.');if(st.hypothesis!=='dirt'||!st.links.dirt)return talk('Какая версия объединяет след на окне и описание распознавания? Сопоставь её и оставь выбранной как ведущую.');st.leading='dirt';move(4);}
      }else if(st.phase===4){
        if(type==='next-action'){st.nextAction=value;render();}
        if(type==='evidence'){toggle(st.evidence,value);render();}
        if(type==='propose'){const action=actions.find(x=>x[0]===st.nextAction);if(!action)return talk('Выбери предложение для квалифицированного специалиста.');if(st.nextAction!=='clean')return talk(action[2]);if(!st.evidence.has('inspect')||!st.evidence.has('doc'))return talk('Нужны два прямых основания: что обнаружено сейчас и как это связано с принципом распознавания. Наблюдения сохранены.');st.work=1;talk(action[2],true);}
        if(type==='work-next'){if(st.work>=3)move(5);else if(st.work>0){st.work++;render();}}
      }else if(st.phase===5){
        if(type==='test-start'&&st.test===0){st.test=1;render();}
        if(type==='early-test'&&st.test===1){if(value==='resume')return talk('Три успешных бутылки — только начало. Закончи полный проход, пустой промежуток и повтор. Возвращать участок к обычной работе рано.');if(value==='replace')return talk('Новых пропусков пока нет — для замены не появилось основания. Завершим сравнение в прежних условиях.');if(value==='continue'){st.test=2;render();}}
        if(type==='test-next'&&st.test>=2&&st.test<4){st.test++;render();}
        if(type==='criterion'){toggle(st.criteria,Number(value));render();}
        if(type==='test-conclusion'){st.testConclusion=value;render();}
        if(type==='accept-test'){if(st.test<4)return talk('Заверши оба прохода и пустой промежуток.');if(st.criteria.size!==4)return talk('Проверь все четыре критерия: распознавание, передачу, отсутствие ложных событий и движение механизма.');if(st.testConclusion==='mechanism')return talk('При трёх бутылках механизм ждал группу. При шести и выполненных условиях он выпустил её. Это ожидаемая работа, оснований для наладки сейчас нет.');if(st.testConclusion==='transfer')return talk('Во всех новых проходах выход совпал со входом. Результаты A и B относятся к проверке после работы, а не к исходному событию.');if(st.testConclusion!=='success')return talk('Выбери заключение по результатам наблюдения.');move(6);talk('Бутылки, сигналы и механизм согласованы. После обслуживания окна сбой в двух проходах не повторился. Запишем выполненное и передадим участок.',true);}
      }else if(st.phase===6){
        if(type==='record'){const [i,j]=value.split(':').map(Number);if(fields[i]&&[0,1].includes(j)){st.record[i]=j;st.invalid=st.invalid.filter(n=>n!==i);render();}}
        if(type==='save-record'){st.invalid=fields.map((f,i)=>st.record[i]===f.correct?-1:i).filter(i=>i>=0);if(st.invalid.length)return talk('Проверь отмеченные строки: запись должна точно описывать наблюдения, работу и проверку. Остальные ответы сохранены.');st.handed=true;render();}
        if(type==='handoff'&&st.handed){st.accepted=true;render();a.say('Результат передан, возобновление согласовано. Оператор возвращает учебный участок в работу.','success');}
        if(type==='record-finish'&&st.accepted){a.success('Ты разобрал сообщение оператора, проверил гипотезу по наблюдениям и оформил результат. Открытие готово для паспорта.');a.root.querySelector('.shift-finish button')?.focus({preventScroll:true});}
      }
    }
    return {start(){a.root.querySelector('.shift-heading').innerHTML='<h1>Бутылка есть. А сигнал?</h1><p>Инженерный участок · разбор случая вместе с наставником</p>';render();},act,done:()=>st.accepted,cleanup(){alive=false;}};
  });
})();
